import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, float, texture, fract, sin, mul, add, sub } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  const group = new Group();
  group.name = 'collection-title';

  const inner = new Group();
  group.add(inner);

  const colors = config.intent?.visualSpec?.colors ?? {};
  const inkHex = colors.ink ?? '#16161d';
  const paperHex = colors.paper ?? '#e8ecf2';
  const accentHex = colors.accent ?? '#ff2a38';
  const surfaceHex = colors.surface ?? '#0b0b10';

  const inkCol = new Color(inkHex);
  const accentCol = new Color(accentHex);
  const surfaceCol = new Color(surfaceHex);

  // --- Backdrop: engineered gradient + subtle grain ---
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();

  const vUv = uv();
  const gradColor = mix(
    vec3(surfaceCol.r, surfaceCol.g, surfaceCol.b),
    vec3(inkCol.r, inkCol.g, inkCol.b),
    smoothstep(float(0.0), float(0.8), vUv.y)
  );

  const gUv = vUv.mul(float(800.0));
  const gVal = sub(
    fract(sin(gUv.x.mul(float(12.9898)).add(gUv.y.mul(float(78.233)))).mul(float(43758.5453))),
    float(0.5)
  );
  const grain = mul(gVal, float(0.015));
  backdropMat.colorNode = add(gradColor, grain);
  backdropMat.transparent = true;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  inner.add(backdrop);

  // --- Feature card textured plane ---
  const cardGeo = new PlaneGeometry(4.2, 2.6);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true });
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, -0.3);
  inner.add(cardMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      cardMat.colorNode = texture(tex, uv());
      cardMat.needsUpdate = true;
    });
  }

  // --- Accent line (signal red, <=10% of frame) ---
  const accentGeo = new PlaneGeometry(0.5, 0.025);
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.colorNode = vec3(accentCol.r, accentCol.g, accentCol.b);
  accentMat.transparent = true;
  const accentLine = new Mesh(accentGeo, accentMat);
  accentLine.position.set(0, 0.78, 0.1);
  inner.add(accentLine);

  // --- Caption label above accent ---
  const labelGeo = new PlaneGeometry(0.04, 0.04);
  const labelMat = new MeshBasicNodeMaterial();
  labelMat.colorNode = vec3(accentCol.r * 0.6, accentCol.g * 0.6, accentCol.b * 0.6);
  labelMat.transparent = true;
  const labelDot = new Mesh(labelGeo, labelMat);
  labelDot.position.set(-0.35, 0.78, 0.1);
  inner.add(labelDot);

  // --- Text: "Collection" headline ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 96;
    const textMesh = ctx.fontAtlas.createText(item.text, {
      fontSize: fontSize,
      color: paperHex,
      align: 'center'
    });
    textMesh.position.set(0, -0.05, 0.15);
    inner.add(textMesh);
  }

  // --- Subtle caption below headline ---
  const captionMesh = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 16,
    color: accentHex,
    align: 'center',
    letterSpacingPx: 3
  });
  captionMesh.position.set(0, -0.55, 0.15);
  inner.add(captionMesh);

  // --- Entrance animation (rise-in + weighted-settle) ---
  inner.position.y = 0.4;
  inner.scale.set(0.97, 0.97, 0.97);

  const tl = gsap.timeline();
  tl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' })
    .to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);

  // --- Cleanup ---
  const allMats = [backdropMat, cardMat, accentMat, labelMat];
  const allGeos = [backdropGeo, cardGeo, accentGeo, labelGeo];

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    allGeos.forEach((g) => g.dispose());
    allMats.forEach((m) => m.dispose());
  };

  return group;
}
